('a5c2c52a-54db-4565-9b1b-f3d1f67ebfa3','b0000000-0000-4000-8000-000000000001','offering',
 'Programa — Entrenamiento Funcional — página 3 — parte 1',
 'Curso: Entrenamiento Funcional.
Fuente oficial: programa StudyX, página 3 de 8.
Entrenamiento
Funcional
01 Online en vivo
Modalidad
02
El entrenamiento funcional rompe con los objetivos
convencionales del entrenamiento clásico.
Esta actividad proporciona una rutina de ejercicios útil para
cualquier persona, sea deportista o no. Consiste en imitar y
perfeccionar los movimientos comunes (hasta los más
osados) de la vida diaria para ayudarnos a conseguir nuestra
mejor forma.
De esta manera lograremos con nuestros alumnos trabajar
todo el cuerpo a la vez y no por músculos aislados como
sucede en los gimnasios de aparatos.
Bienvenidos y gracias por confiar en nosotros.
Objetivos del diplomado
03
Duración: 36 Clases con contenido de lectura + Videos
explicativos + Seminarios complementarios de
diferentes áreas + Actividades prácticas con exámenes
parciales y Final.
Módulos
