Modalidad
02
Antes de empezar, vamos a dar una introducción a lo que
hoy sucede con el proceso fotográfico. Actualmente
contamos con miles de dispositivos que pueden realizar
fotografías, los cuales podríamos reducirlos a estos tres
grupos principales: cámaras, smartphones y tablets. Donde
los últimos dos podrían ser similares pero el tamaño y la
conectividad hacen un poco la diferencia.
Las cámaras digitales ya de por si tienen varios subgrupos,
donde tenemos las compactas, las intermedias o bridge, las
réflex, las mirrorless o sin espejos y las de medio formato.
En cuanto a los celulares y tablets, la principal diferencia es
el tamaño y la conectividad, ya que el término “tablet” se
utiliza para diferenciar a un dispositivo que no contiene chip
