 'Programa — Fotografía Profesional — página 5 — parte 1',
 'Curso: Fotografía Profesional.
Fuente oficial: programa StudyX, página 5 de 10.
Perfil
Profesional
En este curso vamos a aprender a
controlar la cámara manualmente,
la exposición, composición,
iluminación y edición/post
procesado de las fotografías.
Principalmente integrar los nuevos
métodos de fotografiar y editar que
hasta hace diez años no existían.
También aprenderemos a realizar
ediciones con programas
especializados, viendo temas de
edición fotográfica, manipulación
de colores, maquillaje digital,
collage fotográfico y edición de
video.
Una propuesta que le permitirá
explorar las distintas aéreas de este
rubro y así lograr explotar sus
gustos y conocimientos internos, a
los fines de poder tener una salida
laboral o simplemente potenciar tu
hobbie.
