digitales. Tipos de visores.
Clase 2: Aprendiendo a leer una cámara réflex
o mirrorless. Valor de exposición (EV) y
fotómetro. El sensor digital.
Clase 3: Sensibilidad / Velocidad de ISO
Clase 4: Obturador. Tiempo de exposición o
velocidad de obturación.
Clase 5: Apertura de diafragma. Profundidad
de campo. Modificadores de profundidad de
campo.
Clase 6: Distancia focal. Tamaño del sensor y
su relación con la distancia focal
Clase 7: Lente / Objetivo. Categorías de lentes.
Clase 8: Sistema de enfoque y medición.
Zona de Medición. Zonas de enfoque. Modos
de enfoque.
Clase 9: Balance de Blancos (White Balance
‘WB’). Balance de Blancos y Zona de
Medición.
Clase 10: Histograma. Formato y calidad de
imagen. RAW, JPEG y TIFF.
Clase 11: Composición. Secuencia de
Fibonacci.
Temario Fotografía
Profesional
