 'Curso: Introducción a la Pastelería y Repostería.
Fuente oficial: programa StudyX, página 3 de 7.
Introducción a la
Pastelería/Repostería
01 Online en vivo
Modalidad
02
La profesión del pastelero es considerada como un arte,
posee la facultad del ingreso que permite transformar la
materia prima en ricos manjares, propiciando la creatividad.
El pastelero es un artista, no obstante, sus trabajos son
regidos por fórmulas, a las cuales se les debe agregar
imaginación y habilidad manual. Para llevar a cabo un
trabajo de óptima calidad.
El material tiene la finalidad de proporcionar a los alumnos,
los procedimientos técnicos necesarios para el desarrollo de
esta de esta profesión.
Bienvenidos y gracias por confiar en nosotros.
Objetivos del diplomado
03
Duración: 15 Clases con contenido de lectura + Videos
explicativos + Seminarios complementarios de
diferentes áreas + Actividades prácticas con exámenes
parciales y Final.
Módulos
