('0d6f3c2a-e8d9-4a27-9590-44104f8e1b1d','b0000000-0000-4000-8000-000000000001','offering',
 'Programa — Introducción al Vino, la Cata y el Maridaje — página 6 — parte 1',
 'Curso: Introducción al Vino, la Cata y el Maridaje.
Fuente oficial: programa StudyX, página 6 de 9.
Clase 1: Historia del vino. Elaboración de tintos
y blancos. El vino en la Argentina. Historia. El
vino argentino, potencial infinito.
Exportaciones.
Clase 2: Zonas vitivinícolas. Variedades más
utilizadas en el país. Vinos varietales y de
corte. Europa vs Estados Unidos. La
Revolución Californiana.
Clase 3: Degustación de vinos. Catar.
Degustar. Beber. Arte, no ciencia. Color.
Aroma. Sabor. ¿Cómo se bebe un vino para
degustarlo? El vino y el lenguaje.
Clase 4: Copas. Temperatura de servicio.
Etiquetas. Corchos. Accesorios. Maridajes
entre vinos y platos. Armar la propia bodega.
Clase 5: Champagne. Espumosos. Cavas.
Métodos de elaboración. El mercado.
Degustación. Maridajes.
Clase 6: El mundo del vino actual. La
importancia de la relación calidad y valor.
Denominaciones de origen. Las vinotecas.
Apéndice. Breve diccionario enológico.
Programa completo: https://mystudyx.com/diplomado/introduccion-al-vino-la-cata-y-el-maridaje/',
 'active',1,'{"source":"official_program_pdf","course_slug":"introduccion-al-vino-la-cata-y-el-maridaje","offering_code":"vino_cata_maridaje","catalog_url":"https://mystudyx.com/diplomado/introduccion-al-vino-la-cata-y-el-maridaje/","pdf_sha256":"0cafa1420470e6905c62fc81c47032204ed026ab95f024f29241bb213b6f5296","source_page":6,"source_part":1,"extracted_at":"2026-10-29"}'::jsonb),
