('bc6937ed-cd7e-4eee-9037-da0c8e679b0f','b0000000-0000-4000-8000-000000000001','offering',
 'Programa — Introducción al Vino, la Cata y el Maridaje — página 7 — parte 1',
 'Curso: Introducción al Vino, la Cata y el Maridaje.
Fuente oficial: programa StudyX, página 7 de 9.
Clase 8: Reglas de maridaje. Enumeración.
Equilibrio. Potenciando los sentidos.
Clase 9: Los enemigos del vino. Ajo, cebolla,
vinagre, aceto. Los amargos: apio, berro,
alcaucil, endibias, espárragos. Los huevos. Los
salados: de la sardina a las anchoas. Caldos,
consomés y sopas. Embutidos, ahumados y
escabeches. La complejidad del picante.
Clase 10: Los espumosos. Maridajes clásicos,
modernos y exóticos. Versatilidad. Análisis de
la combinación de las burbujas con los
alimentos.
Clase 11: Maridajes por contraposición. Más
allá de las reglas tradicionales. Vinos dulces y
alimentos salados. Vinos ligeros y
elaboraciones picantes. La acidez como
complemento de preparaciones con buen
tenor de carbohidratos.
Clase 12: Vinos para picadas. Las variedades
de uva más versátiles. Combinaciones
