 'Curso: Paisajismo y Jardinería.
Fuente oficial: programa StudyX, página 3 de 8.
Jardinería y
Paisajismo
01 Online en vivo
Modalidad
02
En el Curso de Jardinería y Paisajismo aprenderemos cuáles
son las características principales de los elementos
vegetales, tanto botánicos como estéticos, y a manejarlos
eficientemente a través de técnicas de planificación y
diseño de espacios naturales.
Les dejamos un pensamiento, que queremos compartir con
todos ustedes:
“El amor por el trabajo en el jardín es una semilla que una
vez sembrada, no desaparece nunca".
Gertrude Jekyll, Paisajista.
¡Manos a la obra!
Objetivos del diplomado
03
Duración: 24 Clases con contenido de lectura + Videos
explicativos + Seminarios complementarios de
diferentes áreas + Actividades prácticas + Exámenes
parciales y Final.
