('a1080c95-0c9c-4e84-aa90-2b6f0fcd0102','b0000000-0000-4000-8000-000000000001','offering',
 'Programa — Técnica/o en Depilación Definitiva — página 3 — parte 1',
 'Curso: Técnica/o en Depilación Definitiva.
Fuente oficial: programa StudyX, página 3 de 11.
Técnica/o en
Depilación Definitiva
01 Online en vivo
Modalidad
02
Alrededor del mundo, millones de hombres y mujeres se
depilan a diario. Para la mayoría, esto constituye una
práctica habitual de la vida diaria, pero, para algunos, la
presencia de pelos no deseados acarrea problemas
psicológicos o molestias excesivas asociadas a la depilación
que motivan a pedir ayuda profesional.
Existen diversos métodos de depilación disponibles, algunos
de los cuales producen destrucción permanente del folículo
piloso, considerándose por este motivo definitivo.
En este curso te explicaremos todo lo que necesitas saber
para poder dedicarte a esta profesión.
Objetivos del diplomado
03
Duración: 7 Clases con contenido de lectura + Videos
explicativos + Seminarios complementarios de
diferentes áreas + Actividades prácticas con exámenes
parciales y Final.
Programa completo: https://mystudyx.com/diplomado/tecnica-o-en-depilacion-definitiva/',
