('f035731e-0c20-49b4-afce-22face7dd815','b0000000-0000-4000-8000-000000000001','offering',
 'Programa — Técnica/o en Estética Integral — página 3 — parte 1',
 'Curso: Técnica/o en Estética Integral.
Fuente oficial: programa StudyX, página 3 de 27.
Estética Integral
01 Online en vivo
Modalidad
02
En la actualidad, vivimos en un mundo que prioriza la
imagen personal. La mayoría de las personas, recurre a
centros especializados para el cuidado estético: desde
servicios de manicuría, cosmetología, higiene, hasta
depilación. Es por esto que consideramos de suma
importancia conocer los diferentes servicios estéticos y
poder trabajar desde cada uno de ellos, así como también
poder operar con los diferentes dispositivos de aparatología.
Los técnicos de estética integral llevan a cabo tratamientos
de belleza en las personas para mejorar su aspecto, y para
ayudarles a sentirse mejor consigo mismas. Estos
tratamientos incluyen cosméticos, depilación, tratamientos
faciales, corporales, masajes, entre otros.
